import math

def is_perfect_square(k):
    if k < 0:
        return False
    sqrt_k = int(math.isqrt(k))
    return sqrt_k * sqrt_k == k

A_n = []
for n in range(1, 61):
    T_n = n * (n + 1) // 2
    if is_perfect_square(T_n):
        A_n.append(n)

print(f"Indices n (up to 60) for which T_n is a perfect square: {A_n}")
print(f"The sequence A up to the first 6 elements is: {A_n[:6]}")
